{
  "done": false,
  "tool": "manage_backends",
  "args": {
    "operation": "add",
    "name": "Chain TVL Data",
    "url": "http://localhost:7802",
    "widgets_json": {
      "chains_highchart": {
        "name": "TVL by Chain (Highcharts)",
        "description": "Highcharts rendering of chain TVL.",
        "endpoint": "/chains-highchart",
        "type": "chart-highcharts",
        "params": [
          {
            "paramName": "chain_scope",
            "type": "text",
            "label": "Chain scope",
            "value": "Ethereum",
            "description": "Chain reviewed across chart and table."
          }
        ],
        "w": 20,
        "h": 9
      },
      "chains_table": {
        "name": "Top Chains by TVL",
        "description": "Current TVL of all chains from the desk aggregator.",
        "endpoint": "/chains-table",
        "type": "table",
        "params": [
          {
            "paramName": "chain_scope",
            "type": "text",
            "label": "Chain scope",
            "value": "Ethereum",
            "description": "Chain reviewed across chart and table."
          }
        ],
        "w": 20,
        "h": 9,
        "data": {
          "table": {
            "columnsDefs": [
              {
                "field": "name",
                "headerName": "Chain",
                "cellDataType": "text"
              },
              {
                "field": "tvl_usd",
                "headerName": "TVL ($)",
                "cellDataType": "number",
                "formatterFn": "int"
              },
              {
                "field": "change_1d",
                "headerName": "1d Change",
                "cellDataType": "number",
                "formatterFn": "percent",
                "renderFn": "greenRed",
                "renderFnParams": {
                  "actionType": "sendToAgent",
                  "groupBy": {
                    "paramName": "change_1d"
                  }
                }
              }
            ]
          }
        }
      }
    },
    "apps_json": [
      {
        "name": "Chain Chart Room",
        "description": "Highcharts chain view and TVL table.",
        "tabs": {
          "chart": {
            "id": "chart",
            "name": "Chart",
            "layout": [
              {
                "i": "chains_highchart",
                "x": 0,
                "y": 0,
                "w": 20,
                "h": 9
              }
            ]
          },
          "table": {
            "id": "table",
            "name": "Table",
            "layout": [
              {
                "i": "chains_table",
                "x": 0,
                "y": 0,
                "w": 20,
                "h": 9
              }
            ]
          }
        },
        "groups": [
          {
            "name": "Chain Sync",
            "type": "param",
            "paramName": "chain_scope",
            "widgetIds": [
              "chains_highchart",
              "chains_table"
            ]
          }
        ]
      }
    ]
  }
}

